function rebuildRow(pairs: number[][]): number[] {
  const count = new Map<number, number>();
  for (const [a, b] of pairs) {
    count.set(a, (count.get(a) ?? 0) + 1);
    count.set(b, (count.get(b) ?? 0) + 1);
  }
  let start = 0;
  for (const [v, c] of count) if (c === 1) { start = v; break; }
  const row = [start];
  while (row.length < pairs.length + 1) {
    const last = row[row.length - 1], prev = row.length > 1 ? row[row.length - 2] : null;
    for (const [a, b] of pairs) {
      const other = a === last ? b : b === last ? a : null;
      if (other !== null && other !== prev) { row.push(other); break; }
    }
  }
  return row;
}

