class Solution:
    def rebuildRow(self, pairs: List[List[int]]) -> List[int]:
        count = Counter()
        for a, b in pairs:
            count[a] += 1
            count[b] += 1
        start = next(v for v, c in count.items() if c == 1)
        row = [start]
        while len(row) < len(pairs) + 1:
            last = row[-1]
            prev = row[-2] if len(row) > 1 else None
            for a, b in pairs:
                other = b if a == last else a if b == last else None
                if other is not None and other != prev:
                    row.append(other)
                    break
        return row

