function rebuildRow(pairs: number[][]): number[] {
  const adj = new Map<number, number[]>();
  for (const [a, b] of pairs) {
    if (!adj.has(a)) adj.set(a, []);
    if (!adj.has(b)) adj.set(b, []);
    adj.get(a)!.push(b);
    adj.get(b)!.push(a);
  }
  let start = 0;
  for (const [v, ns] of adj) if (ns.length === 1) { start = v; break; }
  const row = [start, adj.get(start)![0]];
  while (row.length < pairs.length + 1) {
    const ns = adj.get(row[row.length - 1])!;
    const prev = row[row.length - 2];
    row.push(ns[0] === prev ? ns[1] : ns[0]);
  }
  return row;
}

